-- Capacités de monstre communes (décisions R66 à R69 du propriétaire, 2026-10-14 ; docs/decisions-regles.md) : « notées dans des tables à part (pour
-- l'instant juste Nom et Description) histoire de mutualiser les capacités communes », « Elle change pour tous », les fautes de frappe corrigées et
-- fusionnées, « Tout doit être unifié, sauf "Lanceur de sort" » (une liste de sorts par monstre) ; les textes retenus par le chef pour les capacités
-- qui avaient plusieurs écritures (R68) ; « si l'effet ne diffère que d'un chiffre, le mettre modifiable par un slider » (R69 : emplacements « {N} »).
-- Les capacités des créatures invoquées et les bonus du Mage Bleu restent à part (R67) : rien ne change en section 8.
-- - monstre_capacite_commune : 469 capacités (nom, description), rangées par le registre tools/bestiaire/capacites.json ;
-- - monstre_capacite : refaite, la place de chaque capacité sur sa carte (rang, préfixe, capacité commune, liste de sorts) ; 1 762 placements (le doc
--   en écrit 1 762 : « Tome de la corruption niv.1. », collé faute d'espace à la capacité qui le précède sur le Gobelin mage obsolète, est à part) ;
-- - monstre_capacite_valeur : les 32 valeurs d'une carte qui ne sont pas la valeur commune de leur emplacement ;
-- - monstre_rubrique : la rubrique « Capacité(s) » ne garde que sa place et son titre (texte vide) ; rangs inchangés (une modification de la tactique de
--   l'Os du blizzard, rang 11, attend sur le site de dev).
-- Lignes écrites par l'extracteur (node tools/bestiaire/extraire.mjs --sql --tables …), que client/test/bestiaire-extraction.test.mjs compare à la base.
CREATE TABLE monstre_capacite_commune (
  id             TEXT    NOT NULL PRIMARY KEY CHECK (length(id) > 0 AND id NOT GLOB '*[^a-z0-9-]*' AND id NOT GLOB '-*' AND id NOT GLOB '*-'),
  nom            TEXT    NOT NULL CHECK (length(nom) > 0),        -- « Inerte », « Science du critique+ », « Tome de l’ombre niv. 1 »
  nom_cle        TEXT    NOT NULL,                                -- normalize(nom) ; non unique (deux textes d'une même capacité, R68)
  description    TEXT    NOT NULL CHECK (length(description) > 0), -- paragraphes séparés par une ligne vide ; « {N} » = emplacement de valeur commune N (R69)
  liste_de_sorts INTEGER NOT NULL DEFAULT 0 CHECK (liste_de_sorts IN (0, 1)),   -- 1 : chaque carte écrit sa liste de sorts (monstre_capacite.sorts) : « Lanceur de
                                                                                 -- sorts », seule capacité à liste (R66 : « Tout doit être unifié, sauf "Lanceur de sort" »)
  origine        TEXT    NOT NULL REFERENCES famille(id) CHECK (origine = 'monstres'),
  source_ref     TEXT    NOT NULL CHECK (length(source_ref) > 0)  -- la première carte du doc qui l'écrit ; « Décision R68 » pour un texte du propriétaire ;
                                                                  -- « Site de dev › … » pour une capacité créée sur le site
) STRICT;

CREATE INDEX monstre_capacite_commune_nom ON monstre_capacite_commune (nom_cle);

