INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('25h', '25h', '25h', 'Cette créature est capable d’utiliser un sortilège de l’Espace/Temps qui est capable de placement, le sort ne fera rien d’autre que l’effet de placement. Cet IC peut se faire avant, après ou pendant le tour réel de la créature (1 fois par tour)', 0, 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('3-tetes', '3 têtes', '3-tetes', 'Cette créature possède 3 initiatives et des dons différents selon la tête qui joue.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5856');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('acharnement', 'Acharnement', 'acharnement', 'Lorsqu’un sort frappe une cible de magie vulnérable, sa faiblesse s’aggrave d’un cran juste pour l’attaque.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19064');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('adaptation-elementaire', 'Adaptation élémentaire', 'adaptation-elementaire', 'Cette créature ne possède pas la même forme selon l’environnement où on la rencontre, chaque environnement peut être associé à une magie, et lui donne différents bonus :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('alea-negatif', 'Aléa négatif', 'alea-negatif', 'Chaque début de son tour, cette créature va prendre pour cible un ennemi au hasard, lance un D20 et inflige un effet négatif selon le résultat :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('allonge-inattendue', 'Allonge inattendue', 'allonge-inattendue', 'Augmente la portée des sorts d''attaque de +3.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('animosite-rage', 'Animosité (rage)', 'animosite-rage', 'Permet d’avoir une attaque de bec bonus qui vient juste après l''attaque de corps à corps.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7190');
