INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('annule-horloge', 'Annule horloge', 'annule-horloge', 'Si un adversaire fait un jet de dé et que le nombre 6, 12 ou 24 est le résultat, le dé est totalement annulé (que ce soit action ou dégâts). Si c''est l''initiative, elle tombe à 0.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('anti-alignement', 'Anti alignement', 'anti-alignement', 'Inflige +4 dégâts contre les créatures de la Loi et du Chaos.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22640');
