INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('anti-mal-2', 'Anti-mal', 'anti-mal', 'Inflige un bonus de +8 dégâts contre les créatures mauvaises.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20080');
