INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('appels-aux-morts-2', 'Appels aux morts', 'appels-aux-morts', 'Si cette créature tombe en dessous de 20% de santé, elle invoque automatiquement un squelette (cf. Squelette ennemi simple).', 0, 'monstres', 'Bestiaire 2.0 › ligne 18460');
