INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('arme-foudroyante', 'Arme foudroyante', 'arme-foudroyante', 'L’une des armes* de cette créature est de l’élément foudre et est capable de taper dans cet élément ou non.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18758');
