INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaquant', 'Attaquant', 'attaquant', 'Permet d''infliger +5 dégâts avec des armes d''hast.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24112');
