INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaque-immaterielle', 'Attaque immatérielle', 'attaque-immaterielle', 'Les armes de cette créature ignorent les AP données par les armures.', 0, 'monstres', 'Bestiaire 2.0 › ligne 13254');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaque-maudite', 'Attaque maudite', 'attaque-maudite', 'L''attaque de cette créature a l''effet du sort de l''ombre "malédiction" et l''applique automatiquement pendant 1 tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6351');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaque-multiple', 'Attaque multiple', 'attaque-multiple', 'Cette créature peut taper sur 3 axes quand il attaque avec ses armes (Devant, Gauche, Droite) [NOTE : 4 axes quand il est sous la forme 5 lui ajoute derrière lui]', 0, 'monstres', 'Bestiaire 2.0 › ligne 12397');
