INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaque-poison-2', 'Attaque poison', 'attaque-poison', 'Les armes de cette créature obligent un jet de vigueur à la cible, si cette dernière rate, elle se prend “Poison 1”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20499');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaque-sanglante', 'Attaque sanglante', 'attaque-sanglante', 'Les armes naturelles de cette créature obligent le jet de vigueur pour ne pas prendre “Saignement 1”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18066');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attaque-sanglante-2', 'Attaque sanglante', 'attaque-sanglante', 'L’une des armes* de cette créature oblige le jet de vigueur pour ne pas prendre “Saignement 1”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6466');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attendrissement', 'Attendrissement', 'attendrissement', 'En échange de 3IC, cette créature peut forcer le jet de fermeté à sa cible, si cette dernière rate, elle ne peut pas attaquer à son prochain tour. (recharge de 3 tours)', 0, 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('attrape-moi', 'Attrape moi', 'attrape-moi', 'Les jets de défense possèdent un bonus de 5% par ennemi empoisonné sur le terrain (maximum 20%).', 0, 'monstres', 'Bestiaire 2.0 › ligne 20499');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('au-dela-de-la-portee', 'Au-delà de la portée', 'au-dela-de-la-portee', 'Cette créature peut utiliser les obstacles sur le terrain comme extension de portée et frapper les ennemis qui sont à deux cases d’eux. Ses armes font deux fois moins de dégâts quand il use de cette méthode pour atteindre un ennemi (sauf quand il lui reste moins de 40% de sa santé).', 0, 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aucune-fuite', 'Aucune fuite', 'aucune-fuite', 'Si jamais il y a impossibilité de fuir ou qu’un état de peur est tenté contre lui = +5 dégâts, +1 Vitesse le temps que la situation se débloque.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-de-frayeur', 'Aura de frayeur', 'aura-de-frayeur', 'Sur un zone de 3 autour de lanceur, force le jet de fermeté aux adversaires pour ne pas prendre “peur 1”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18400');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-de-grand-chef', 'Aura de grand chef', 'aura-de-grand-chef', 'Donne un bonus de +5 aux dégâts de ses alliés tant qu’il est encore debout.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-de-peur', 'Aura de peur', 'aura-de-peur', 'Inflige un malus de -10% au jet de défense aux ennemis à deux cases.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-de-predateur', 'Aura de prédateur', 'aura-de-predateur', 'Cette créature est si effrayante qu’il empêche toute contre attaque contre lui.', 0, 'monstres', 'Bestiaire 2.0 › ligne 27654');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-des-affaiblis', 'Aura des affaiblis', 'aura-des-affaiblis', 'Sur une zone de 3 autour du lanceur, impose un malus de 10% aux jets d’arme lourde/arme légère/arbalète/arc/magie/concentration des adversaires.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18400');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-des-brises', 'Aura des brisés', 'aura-des-brises', 'Sur une zone de 3 autour du lanceur, impose un malus de 10% aux jets d’esquive/parade/psychologie des adversaires.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18400');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-dombre', 'Aura d’ombre', 'aura-dombre', 'Permet d''annuler totalement une frappe de l’élément lumière, que ce soit dégâts ou effets secondaires. (Réaction 1 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-du-general', 'Aura du général', 'aura-du-general', 'Les ennemis sur le terrain ont un malus de 5% à tous leurs jets tant que la créature est vivante.', 0, 'monstres', 'Bestiaire 2.0 › ligne 28033');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aura-lunaire', 'Aura lunaire', 'aura-lunaire', 'Réduit les dégâts de glace, feu, lumière et ombre de 6.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('aveugle-naturel', 'Aveugle naturel', 'aveugle-naturel', 'Cette créature est naturellement aveugle, ce qui l''immunise de tous les effets, attaques ou altérations d’état lié à la vue. Cet aveuglement ne l’empêche pas de connaître son environnement et de savoir où sont ses ennemis, la Perception n’est donc pas endommagée.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20564');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('balayage', 'Balayage', 'balayage', 'Permet de sacrifier 35% de réussite pour faire une attaque qui va toucher toutes les cibles autour (y compris en diagonale).', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('balayage-2', 'Balayage', 'balayage', 'Cette créature possède une arme (queue) qui est capable de toucher toutes les cibles autour d’elle en échange de 30% de réussite.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('baroud', 'Baroud', 'baroud', 'Si la santé tombe à 0, possède un dernier tour d’action, si sa santé remonte en positif pendant ce dernier tour, le don est de nouveau actif.', 0, 'monstres', 'Bestiaire 2.0 › ligne 12461');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('bien-sournois', 'Bien sournois', 'bien-sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 3d4 dégâts en plus des dégâts de l''arme.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24254');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('blessure-chakratique', 'Blessure chakratique', 'blessure-chakratique', 'Cette créature exploite le chakra de ses adversaire à son avantage, elle obtient un bonus de 1 dégât à ses attaques par 5 chakra courant dans la réserve de sa cible. Quand ses ennemis utilisent du chakra, si leur score de réussite est au dessus de 75, ils perdent le quart du coût en chakra du sort en santé (minimum 1 santé).', 0, 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('blizzard-permanent', 'Blizzard permanent', 'blizzard-permanent', 'Invoque la météo “tempête de neige” en entrant sur le terrain et fait perdurer tant que personne ne la change.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5653');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('bond', 'Bond', 'bond', 'Cette créature est capable de faire un bond équivalent à sa vitesse x2 en échange de 3IC.', 0, 'monstres', 'Bestiaire 2.0 › ligne 3603');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('bouclier-de-feu', 'Bouclier de feu', 'bouclier-de-feu', 'Projette des flammes inesquivables qui infligent 2d6 en réponse à toutes agressions au corps à corps.', 0, 'monstres', 'Bestiaire 2.0 › ligne 14632');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('brasier-unifie', 'Brasier unifié', 'brasier-unifie', 'Quand la créature perd 25% de santé, elle va se diviser en deux, ces deux nouveaux être se partagent la santé courante mais conserve la puissance de base. Ce processus peut se faire 3 fois maximum. Une fois que la première division à eu lieu, les créatures nouvelles n''ont qu’une seule initiative.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('brouillard-de-lassassin', 'Brouillard de l’assassin', 'brouillard-de-lassassin', 'Pose automatiquement la météo “brouillard obscur” et le fait perdurer tant qu’il n’est pas changé. Les attaques discrètes sont garanties à chacune de ses attaques tant que la météo est présente.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('broussaille', 'Broussaille', 'broussaille', 'Cette créature perd un cran de résistance au Feu et à la Glace, n’aggrave pas les faiblesses.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18965');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('broyage', 'Broyage', 'broyage', 'Les armes naturelles de cette créature sont capables, sur un coup critique, d’infliger des malus caractéristiques aléatoires. (cumulable)', 0, 'monstres', 'Bestiaire 2.0 › ligne 23836');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('brulure-chakratique', 'Brûlure chakratique', 'brulure-chakratique', 'Tant qu’elle est sur le terrain, cette créature augmente les coûts en chakra de 50% pour ses ennemis.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('cadeau-chakratique', 'Cadeau chakratique', 'cadeau-chakratique', 'Cette créature peut donner une partie de son chakra à une cible. (3 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('calque-amitie-amour', 'Calque amitié/amour', 'calque-amitie-amour', 'Cette créature est capable de calquer les capacités d’une créature que sa cible affectionne dans son cœur en se métamorphosant en cette dernière. La métamorphose cesse quand l’adversaire est dans le coma ou quand le métamorphe tombe en dessous de 50% de santé (elle copie les carac, compétences, don, race, classe, magie mais garde ses attributs)', 0, 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('camouflage', 'Camouflage', 'camouflage', 'Cette créature inflige toujours des dégâts discrets tant qu''elle est dans le bon décor (eau).', 0, 'monstres', 'Bestiaire 2.0 › ligne 12239');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('camouflage-2', 'Camouflage', 'camouflage', 'Dans le bon environnement (champs), cette créature peut complètement disparaître et obliger ses adversaires à le chercher. Peut profiter d’une attaque discrète.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24322');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('camouflage-3', 'Camouflage', 'camouflage', 'Dans le bon environnement (marais, eau), cette créature peut complètement disparaître et obliger ses adversaires à le chercher. Peut profiter d’une attaque discrète.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('caprice-meteorologique', 'Caprice météorologique', 'caprice-meteorologique', 'La météo change tous les 3 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 15057');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('caprice-meteorologique-plus', 'Caprice météorologique+', 'caprice-meteorologique', 'La météo change tous les 2 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 15128');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('caprice-meteorologique-plus-plus', 'Caprice météorologique++', 'caprice-meteorologique', 'La météo change tous les tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 15203');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('carapace-huileuse', 'Carapace huileuse', 'carapace-huileuse', 'Les dégâts physiques infligés sur lui diminue de 5 en dégâts mais prend 5 dégâts de plus contre les dégâts de feu et de foudre.', 0, 'monstres', 'Bestiaire 2.0 › ligne 705');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('celerite', 'Célérité', 'celerite', 'Cette créature possède une action en plus par tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 4711');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('champ-protecteur', 'Champ protecteur', 'champ-protecteur', 'A chaque coup que prend la créature, un champ de force va être invoqué et peut encaisser la même quantité de dégâts que le coup précédant. Pour qu’un champ de force apparaisse, il faut attendre que la créature n’est plus rien et qu’elle prenne un coup.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('changement-detat', 'Changement d’état', 'changement-detat', 'Cette créature est dans une matière qui fait qu’il peut changer aléatoirement de forme entre les différents états de l’eau : Liquide, Gazeux et Solide. Ces différents états lui donne des particularités :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('charge', 'Charge', 'charge', 'Cette créature est capable d’infliger 1d de dégâts supplémentaire si elle parcourt plus de 4 cases avant son attaque.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6351');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('charge-chakratique', 'Charge chakratique', 'charge-chakratique', 'Quand la réserve de chakra atteint 100%, peut faire une charge sur une cible dont la portée correspond au sprint de la créature. Une fois cette attaque faite, la réserve de chakra retombe à 0.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7521');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('charge-piquante', 'Charge piquante', 'charge-piquante', 'Au lieu d''envoyer les pics dans une direction en cône, la créature peut les utiliser pour faire une charge en avant qui inflige 20 dégâts de frappe par tour cumulé. Elle s’arrête au premier gros obstacle. Elle ne prend pas de dégâts de recul mais les pics disparaissent et la créature perd 1 tour et sa posture.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('charge-porcine', 'Charge porcine', 'charge-porcine', 'Permet d''avoir un bonus de +2 à la vitesse. Possible uniquement en ligne droite et si il y a une cible à l''arrivée.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('charge-sans-peur', 'Charge sans peur', 'charge-sans-peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7256');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('chargement-bleu', 'Chargement bleu', 'chargement-bleu', 'Cette créature possède une réserve de chakra vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('chargement-bleu-2', 'Chargement bleu', 'chargement-bleu', 'Cette créature possède une réserve de chakra vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('chargement-contact', 'Chargement contact', 'chargement-contact', 'Permet de charger un sort d''attaque lvl1 ou lvl2 le premier tour et de l''utiliser en même temps que l''attaque de contact le tour suivant.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6083');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('chef-non-mort', 'Chef non-mort', 'chef-non-mort', 'Si d’autres non-mort sont présents sur le terrain et sont ses alliés : +4 dégâts et +2 Initiative tant que la créature est en vie (non cumulable).', 0, 'monstres', 'Bestiaire 2.0 › ligne 27972');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('climato-choix', 'Climato-choix', 'climato-choix', 'Invoque une météo avantageuse pour ses alliés au début du combat.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24463');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('climato-egoiste', 'Climato-égoïste', 'climato-egoiste', 'Les bonus de la météo ne s’appliquent que pour lui et ses alliés.', 0, 'monstres', 'Bestiaire 2.0 › ligne 4881');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('climatoptimiste', 'Climatoptimiste', 'climatoptimiste', 'Double les effets positifs de la météo pour lui et ses alliés.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('climatosceptique', 'Climatosceptique', 'climatosceptique', 'Cette créature ne prend aucun effet négatif de la météo.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('coeur-prismatique', 'Coeur prismatique', 'coeur-prismatique', 'Cumule les dégâts encaissés pendant le tour où le cœur est exposé, inflige un coup qui touchera tout le monde sur le terrain avec un malus de 30% pour le jet de défense (dégâts du coup = dégâts cumulés ÷ 10). Ce coup ignore 50% des AP et AM.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('concentration-colore', 'Concentration coloré', 'concentration-colore', 'Utilise la concentration au lieu de la magie pour lancer ses sorts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6083');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('concentre', 'Concentré', 'concentre', 'Cette créature est toujours en focus.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5856');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('contact', 'Contact', 'contact', 'Cette créature à un bonus de +3 aux dégâts avec les armes et un bonus de 5% Arme lourde et légère.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11718');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('copie-brumeuse', 'Copie brumeuse', 'copie-brumeuse', 'Cette créature imite ses adversaires en créer des copies d’ombre de ces derniers, la puissance de ces copies dépend entièrement des originaux. L’une des copies est tangible et est le seul moyen d’infliger des dégâts à l’élémentaire. Chaque attaque qui est tenté contre lui (réussi ou raté), il se déplace de copie, un jet d’observation/distinction peut être tenté au début du tour pour repérer celui qui est tangible.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('cordor', 'Cord’or', 'cordor', 'Cette créature est immunisée à toutes les altérations, à tous les sorts qui ne causent pas de dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21100');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('corps-de-cyclone', 'Corps de cyclone', 'corps-de-cyclone', 'Cette créature se place au centre (5x5) de la battlemap et force ses ennemis à aller dans les coins. Les ennemis doivent se déplacer dans le cyclone au centre pour lui faire des dégâts. Il est nécessaire de réussir des jet de stabilité/réflexe pour pouvoir avancer dans la tornade, un échec divise par 2 la vitesse pour 1 tour. Il est impossible de sprinter dans la tornade. Si jamais un ennemi retombe dans la tornade, il est repoussé de 1d4 cases en arrière. Au sein du cyclone, les projectiles et attaques magiques ne fonctionnent pas et ne peuvent pas atteindre le centre.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('corps-de-feu', 'Corps de feu', 'corps-de-feu', 'Chaque attaque physique/magique au contact qu''un assaillant prodigue lui oblige de faire un de vigueur pour ne pas subir "Brûlure 1".', 0, 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('corps-electrique', 'Corps électrique', 'corps-electrique', 'Chaque attaque au contact qu''un assaillant prodigue lui oblige de faire un de vigueur pour ne pas subir "Paralysie 1".', 0, 'monstres', 'Bestiaire 2.0 › ligne 10386');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('corps-precieux', 'Corps précieux', 'corps-precieux', 'Le matériau Argent ne possède pas son bonus de dégâts contre cette créature.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20956');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('coup-alternatif', 'Coup alternatif', 'coup-alternatif', 'Permet de choisir si l''attaque va prendre en compte l''armure physique ou bien l''armure magique de la cible.', 0, 'monstres', 'Bestiaire 2.0 › ligne 4881');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('coup-perturbateur', 'Coup perturbateur', 'coup-perturbateur', 'La cible aura un malus de 10% à son esquive ou parade.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26201');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('couple-extremite', 'Couple extrémité', 'couple-extremite', 'Les tours impairs = Commence en premier le tour. Les tours pairs = Commence en dernier le tour', 0, 'monstres', 'Bestiaire 2.0 › ligne 16901');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('crache-chakra', 'Crache chakra', 'crache-chakra', 'Tous les 10% de santé perdu, cette créature libère “Boule de chakra” sur tous les ennemis sur le terrain, ce sort va infliger 6d6 dégâts magiques (comme si elle était surchargé).', 0, 'monstres', 'Bestiaire 2.0 › ligne 28094');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('crache-chakra-plus', 'Crache chakra+', 'crache-chakra', 'Tous les 10% de santé perdu, cette créature libère “Boule de chakra” sur tous les ennemis sur le terrain, ce sort va infliger 7d6 dégâts magiques (comme si elle était surchargé)', 0, 'monstres', 'Bestiaire 2.0 › ligne 28193');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('crache-feu', 'Crache feu', 'crache-feu', 'Contre 3IC, cette créature peut cracher une gerbe de flamme qui va à 3 PO en ligne droite et touché toutes les créatures dans la zone, inflige 3d6 dégâts. Coûte 5 chakra.', 0, 'monstres', 'Bestiaire 2.0 › ligne 13917');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('crache-spore', 'Crache spore', 'crache-spore', 'Crache des spores dans une zone de 2 cases autour qui force un jet de vigueur, si raté impossible de bouger ET de faire l''action en même temps pour le prochain tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 28261');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('craquellement', 'Craquellement', 'craquellement', 'Les armes qui le frappent directement et qui font 91 ou plus à leur jet perdent un cran de solidité.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('cri-dalpha', 'Cri d''Alpha', 'cri-dalpha', 'Oblige les adversaires à faire un jet de calme pour ne pas perdre 1 tour. Les créatures canines non apprivoisées fuient automatiquement. (Action 1 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('cri-repoussant', 'Cri repoussant', 'cri-repoussant', 'Les dégâts sonores pousse les adversaire de 2 cases en arrière et leur fait perdre 1 de vitesse pour leur prochain tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7379');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('critique-alterant', 'Critique altérant', 'critique-alterant', 'L’arme de cette créature, sur un coup critique, est capable d''obliger le jet de vigueur/fermeté pour ne pas que la cible prenne l’altération d’état liée à sa magie (aléatoire si elle en a plusieurs)', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('critique-venimeuse', 'Critique venimeuse', 'critique-venimeuse', 'Une attaque en réussite critique va automatiquement infliger le stade 1 d’empoisonnement à la victime jusqu’au prochain remède, et ceux peu importe les résistances de la cible (sauf immunité).', 0, 'monstres', 'Bestiaire 2.0 › ligne 20499');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('croc-vert', 'Croc vert', 'croc-vert', 'L’attaque de morsure de cette créature possède également la propriété du jet de vomi et l’inflige juste après l''attaque.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21642');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('cuisson-absolue', 'Cuisson absolue', 'cuisson-absolue', 'La peau de cette créature réagit aux éléments qu’on lui inflige, changeant sa peau et lui donne des propriétés. Cet état dure 3 tours tant qu’un autre élément n’est pas utilisé pour le remplacer, au bout de 3 tours, il redevient neutre. Utiliser un élément contraire à celui actif enclenche une “contre-cuisson”, l’effet de contre cuisson peut être esquiver ou parer s’il inflige des dégâts (sauf contre indication).
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('dans-mon-element', 'Dans mon élément', 'dans-mon-element', 'Si cette créature se retrouve dans un environnement lié à sa magie (météo ou terrain), inflige un bonus de +7 à tous les dégâts, +3AM et AP, +5% à tous les jets de dés et +1% à la RC.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('de-marbre', 'De marbre', 'de-marbre', 'Cette créature est totalement immunisée aux dégâts et effets négatifs des magies d’Espace/Temps et de Vide.', 0, 'monstres', 'Bestiaire 2.0 › ligne 14337');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('debut-transparent', 'Début transparent', 'debut-transparent', 'Au début du tour, la première attaque contre lui se fera avec un désavantage.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('defense-infranchissable', 'Défense infranchissable', 'defense-infranchissable', 'Les AP de cette créature ne peuvent pas être diminuées ou ignorées par des effets de sorts ou d’armes.', 0, 'monstres', 'Bestiaire 2.0 › ligne 14906');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('defense-prismatique', 'Défense prismatique', 'defense-prismatique', 'Quand un coup a été encaissé d’un certain élément, sa résistance à ce dernier augmente pendant 1 tour (cumulable).', 0, 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('defenseur', 'Défenseur', 'defenseur', 'Cette créature est toujours en défensive.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5856');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('deflagration', 'Déflagration', 'deflagration', 'Sacrifie la valeur de AP et AM pour les ajouter comme modificateur aux dégâts pendant 3 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9916');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('degustation-deau', 'Dégustation d’eau', 'degustation-deau', 'Absorbe les dégâts de l’élément eau, ce qui lui donne +5 dégâts à la prochaine attaque en plus de le soigner à hauteur de 5d6.', 0, 'monstres', 'Bestiaire 2.0 › ligne 28261');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('demi-sante', 'Demi-santé', 'demi-sante', 'Cette créature a deux fois moins de santé.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('dent-en-acier', 'Dent en acier', 'dent-en-acier', 'La morsure ignore 4 AP.', 0, 'monstres', 'Bestiaire 2.0 › ligne 27851');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('destruction', 'Destruction', 'destruction', 'Le coup critique de cette créature retire automatiquement un cran de solidité à l’arme ou morceau d’armure.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19436');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('detachement', 'Détachement', 'detachement', 'Cette créature est capable de retirer une partie de son corps pour l’utiliser comme une arme, elle perd 10% de sa santé en faisant ça.', 0, 'monstres', 'Bestiaire 2.0 › ligne 17592');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-de-larriere', 'Devoir de l''Arrière', 'devoir-de-larriere', 'Cette créature est ingénieuse, elle est capable de faire un balayage devant elle avec son arme en échange de 15% de réussite pour pouvoir toucher 3 cibles en 1 coup et de taper avec son arme qui dispose d’une portée de 1-3. Elle ne peut pas être désarmer.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18897');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-de-lattaquant', 'Devoir de l’Attaquant', 'devoir-de-lattaquant', 'Cette créature est puissante, il est capable d’utiliser son arme en mordhau en plus d’avoir un bonus de +5* aux dégâts. Son style de combat est si particulier qu’il empêche toute contre-attaque et son lien profond avec son arme fait qu’il ne peut pas être désarmé.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9990');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-de-leclaireur', 'Devoir de l’Éclaireur', 'devoir-de-leclaireur', 'Cette créature est perspicace, elle dispose d’une portée d’attaque qui va sur tout le terrain, ses attaques sont si rapides que la cible a un malus de 10% pour se défendre et une fois par tour elle peut ignorer une attaque d’opportunité.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5793');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-de-legide', 'Devoir de l’Égide', 'devoir-de-legide', 'Cette créature est robuste, il est capable de bloquer un adversaire dans sa zone d’influence mais également d’imposer un désavantage à ce même adversaire si il tente une attaque à distance ou un sort sur une autre cible que lui. Il peut bloquer 4 adversaires comme ça.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7721');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-de-lexecuteur', 'Devoir de l’Exécuteur', 'devoir-de-lexecuteur', 'Cette créature est vicieuse, elle dispose d’un bonus à la vitesse de +1, à l’Initiative de +4, elle est capable d’attaque sournoise qui lui donne un bonus de 1d8 dégâts en plus de son arme. Elle est également capable de passer dans les zones d’influences sans déclencher des attaques d’opportunités.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19315');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-du-magicien', 'Devoir du Magicien', 'devoir-du-magicien', 'Cette créature versatile, anciennement du Potentiel Illimité, est capable d’utiliser tous les sorts d’attaques et d’entraves de niveau 1 en plus d’avoir un bonus de 5 aux dégâts des sorts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10532');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('devoir-final', 'Devoir final', 'devoir-final', 'La fusion ultime de ceux qui sont encore lié à leur devoir, il dispose de tous les avantages des autres fantômes du Cortège, donc il possède :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('diagonale-incoherente', 'Diagonale incohérente', 'diagonale-incoherente', 'Les diagonales comptent pour 1 case de déplacement au lieu de 2.', 0, 'monstres', 'Bestiaire 2.0 › ligne 705');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('distributeur-de-degats', 'Distributeur de dégâts', 'distributeur-de-degats', 'Les attaques physiques ou magiques de cette créature font 2 fois moins de dégâts mais elles sont capables de se distribuer aux ennemis qui sont trop proches de la cible initiale. Si un ennemi est à 3 cases ou moins de la cible initiale, il prend les dégâts et le distribuera si un autre ennemi est trop proche de lui, etc … Les ennemis ne peuvent pas prendre 2 fois l’attaque (impossible de faire une boucle infini).', 0, 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('distributeur-de-foudre', 'Distributeur de foudre', 'distributeur-de-foudre', 'Chaque attaque de l’élément foudre va se distribuer à la cible la plus proche de la première (maximum 3 PO) et infliger la moitié des dégâts et ainsi de suite …', 0, 'monstres', 'Bestiaire 2.0 › ligne 14179');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('double-attaque', 'Double attaque', 'double-attaque', 'Cette créature possède deux armes et peut les utiliser en ambidextrie (avec les malus réduit à 10% et 20% pour les attaques)', 0, 'monstres', 'Bestiaire 2.0 › ligne 26651');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('doublette-parfaite', 'Doublette parfaite', 'doublette-parfaite', 'Les malus pour toucher avec deux armes descendent respectivement à 10% pour la première arme et 20% pour la seconde arme.', 0, 'monstres', 'Bestiaire 2.0 › ligne 15637');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('duelliste', 'Duelliste', 'duelliste', '(Contre un seul ennemi) Bonus de 5% au jet de défense, +3 dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9857');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('dynamo', 'Dynamo', 'dynamo', 'Cette créature brille si fort que tous les jets offensifs dirigés contre elle ont un malus de 10% à la réussite.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1597');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('ecailles-protecteurs', 'Écailles protecteurs', 'ecailles-protecteurs', 'Les écailles de cette créature annulent 4 dégâts à chaque première attaque d’un tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7846');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('eclatement-en-bois', 'Éclatement en bois', 'eclatement-en-bois', 'Action utilisable tous les 5 tours, cette créature peut projeter des éclats de bois acérés dans un rayon de 4 cases autour de lui. Toutes les créatures situées dans la zone subissent 6d6 dégâts de taille.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11911');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('ecrasement', 'Écrasement', 'ecrasement', 'Le poids de cette créature est assez grand pour faire des dégâts colossaux contre les créatures deux fois moins grandes que lui. Par une action, cette créature peut faire un gros plaquage sur une ou plusieurs créatures plus petites qu’elle, les créatures doivent faire un test de réussite (95 ou moins) pour ne pas tomber dans le coma immédiatement.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('effondrement-chakratique', 'Effondrement chakratique', 'effondrement-chakratique', 'Son chakra s’effondre et sa magie est hors de contrôle, cette créature obtient quatres dons selon si elle est mono magie ou bi-magie. Voir tableau plus bas.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22828');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('egide', 'Égide', 'egide', 'Permet de survivre à 1 santé contre une attaque qui est censée vous mettre dans le coma. Marche qu’une fois.', 0, 'monstres', 'Bestiaire 2.0 › ligne 2581');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('elan-fulgurant', 'Élan fulgurant', 'elan-fulgurant', 'Quand la créature encaisse un coup, il peut se déplacer gratuitement devant un ennemi. Ne provoque pas d’attaque d’opportunité. (Réaction 1 fois/tour)', 0, 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('elasticite', 'Élasticité', 'elasticite', 'La portée des attaques augmente de 2.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('element-aleatoire', 'Élément aléatoire', 'element-aleatoire', 'Cette créature peut être de différentes formes et possède un bonus différent selon la magie auquel il est relié. Et avec tout ça, une de ses armes* naturelles est capable d''infliger l’élément relié.
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('element-arcane', 'Élément Arcane', 'element-arcane', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “surcharge magique 1”. L’arme peut taper dans l’élément associé et ses sorts d’arcane infligent également un bonus de +3 aux dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1784');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('element-controle', 'Élément contrôlé', 'element-controle', 'L’attaque de cette créature peut taper dans deux éléments à la fois, aucun élément, un seul à la fois et ceux à volonté.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('element-corruption', 'Élément Corruption', 'element-corruption', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “surcharge magique 1”. L’arme peut taper dans l’élément associé et ses sorts d’arcane infligent également un bonus de +3 aux dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 3912');
