INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('embuscade-poisseuse', 'Embuscade poisseuse', 'embuscade-poisseuse', 'Si cette créature attaque alors qu''elle est dans l''obscurité, sur un marais, un terrain corrompu = +3 dégâts, +2% à la réussite critique', 0, 'monstres', 'Bestiaire 2.0 › ligne 705');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('encrier', 'Encrier', 'encrier', 'Chaque tir réussi a {5}% d’appliquer 2d6 points de corruption et réduit de {5}% les jets pour résister à une altération d''état.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11032');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('equilibre', 'Équilibré', 'equilibre', 'Réduit de 5% le malus de la deuxième arme.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('esclave-de-la-conscience', 'Esclave de la conscience', 'esclave-de-la-conscience', 'Si un corps humanoïde est disponible sur le terrain, cette créature est capable de le parasité pour en faire un allié (invoque un squelrail)', 0, 'monstres', 'Bestiaire 2.0 › ligne 12816');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('esprit-de-meute', 'Esprit de meute', 'esprit-de-meute', 'Cette créature gagne un bonus de +5% à tous ses jets par alliés dans une zone de 2 cases autour de lui.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10053');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('etat-altere', 'État altéré', 'etat-altere', 'Les armes de cette créature ont 25% de chance de forcer un jet pour ne pas prendre une altération d’état mais ce dernier change selon l’état de la créature :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('etats-parfaits', 'États parfaits', 'etats-parfaits', 'La résistance obtenue par l’état solide et gazeux deviennent des immunités.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8843');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('etre-de-l-arcane', 'Être de l‘Arcane', 'etre-de-l-arcane', 'Cette créature peut utiliser tous les sorts de la magie de l’arcane de son niveau.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8707');
