INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('excitation-de-la-chair', 'Excitation de la chair', 'excitation-de-la-chair', 'Plus le temps avance, plus cette créature obtient des amplification permanente sur lui :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('explosion-lumineuse', 'Explosion lumineuse', 'explosion-lumineuse', 'Lors de sa mort, il va exploser dans une explosion faite de lumière qui force le jet de vigueur à tous ceux qui sont à 5 cases ou moins de lui, si les cibles ratent, elles prennent "Aveuglement 2".', 0, 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('explosion-noire', 'Explosion noire', 'explosion-noire', 'Si cette créature perd 25% de sa santé max alors qu’il n’est pas enflammé, il libère de la matière partout autour de lui, obligeant un jet de parade/esquive avec un malus de 20% à tous ceux présent sur le terrain. Inflige 2d6 de corruption et 30 dégâts neutre (réduisible par l’AM).', 0, 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('explosion-nuageuse', 'Explosion nuageuse', 'explosion-nuageuse', 'Capable de libérer le nuage en une grosse explosion sur tout le terrain. Inflige 1d4 multiplié par le nombre de compteurs consommés. Inflige un contre coup qui correspond à la moitié des dégâts infligés. Réussir un jet de défense divise par 2 les dégâts réussi mais ne les annule pas.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('face-ou-face', 'Face ou Face', 'face-ou-face', 'L’ogre est capable d''activer temporairement ses deux têtes en même temps. Ce qui fait qu’elle combine tous les avantages en défense. Dure 3 tours. (1 fois par combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fait-de-verre', 'Fait de verre', 'fait-de-verre', 'Cette créature possède énormément de résistances magiques mais possède une forte vulnérabilité contre les dégâts sonores.', 0, 'monstres', 'Bestiaire 2.0 › ligne 17754');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fermete', 'Fermeté', 'fermete', 'Cette créature ne subit aucun dégâts de recul et inflige un bonus de +5 dégâts si elle fait une attaque suivie d’un déplacement qui a consommé toute sa vitesse.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19375');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('folie-de-guerre', 'Folie de guerre', 'folie-de-guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7902');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fondu', 'Fondu', 'fondu', 'Cette créature est faite d''un métal fondu et possède ainsi des propriétés défensives qui correspondent à son matériau et qui détermine son échelle de puissance.
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('forcareno', 'Forcaréno', 'forcareno', 'Cette créature a un bonus de +1 à la vitesse et +4 aux dégâts tant qu’elle est sur le terrain sable ou que la météo “tempête de sable” est activée.', 0, 'monstres', 'Bestiaire 2.0 › ligne 17241');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('force-demesuree', 'Force démesurée', 'force-demesuree', 'Cette créature peut dépasser la limite de Force de 1.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('force-dours', 'Force d’ours', 'force-dours', 'Cette créature inflige +10 dégâts avec toutes ses armes.', 0, 'monstres', 'Bestiaire 2.0 › ligne 23710');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('force-solaire', 'Force Solaire', 'force-solaire', 'Perd 20% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 s''il y a la météo "grand soleil").', 0, 'monstres', 'Bestiaire 2.0 › ligne 25588');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('force-solaire-plus', 'Force Solaire+', 'force-solaire', 'Perd 10% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 si il y a la météo "grand soleil").', 0, 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('force-solaire-plus-plus', 'Force Solaire++', 'force-solaire', 'Perd 5% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 si il y a la météo "grand soleil").', 0, 'monstres', 'Bestiaire 2.0 › ligne 25701');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('forme-changeante', 'Forme changeante', 'forme-changeante', 'Cette créature à tous les débuts de tour (juste après l''initiative et avant tout le monde) change aléatoirement de forme et ainsi les bonus qu''elle possède, il y a 8 formes :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('forme-meteo', 'Forme météo', 'forme-meteo', 'Cette créature possède une structure particulière qui fait qu’elle se modifier selon la météo :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('forme-meteo-plus', 'Forme météo+', 'forme-meteo', 'Cette créature possède une structure particulière qui fait qu’elle se modifier selon la météo, elle possède également 10% de chance de forcer un jet de vigueur/fermeté à son adversaire pour ne pas qu’il encaisse l’altération d’état lié à son/ses élément(s) :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fouisseur', 'Fouisseur', 'fouisseur', 'Cette créature peut plonger dans le sol pour attaquer par le bas une autre, ça lui demande un tour complet pour pouvoir attaquer mais bénéficie d’un bonus de +5 dégâts quand l’attaque fait mouche.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20564');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fourrure-de-roche', 'Fourrure de roche', 'fourrure-de-roche', 'Cette créature est capable d’augmenter ses AP de 5 pendant 3 tours. (IC - 1 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 20325');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fracas', 'Fracas', 'fracas', 'Une arme* de cette créature est capable de se détruire et toucher ceux qui sont à 2 cases autour de la zone d’impact.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fragilite-tranchante', 'Fragilité tranchante', 'fragilite-tranchante', 'Chaque fois qu’il subit une attaque physique, des éclats de glace sèche sont projetés autour de lui (2d6 dégâts dans une zone de 3 cases autour de lui).', 0, 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('frappe-confuse', 'Frappe confuse', 'frappe-confuse', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “confusion 1”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 12177');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('frappe-poison', 'Frappe poison', 'frappe-poison', 'L’arme de la créature possède une chance d’empoisonnement. Chaque attaque a 25% de chance d’obliger un jet de vigueur à la victime, si elle rate, elle prend “Poison 1”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 27915');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('fureur-animale', 'Fureur animale', 'fureur-animale', 'Chaque attaque avec l’arme de corps à corps sera systématiquement suivie d’une attaque de morsure qui infligera 2d10 de dégâts d’estoc.', 0, 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('general-non-mort', 'Général non-mort', 'general-non-mort', 'Si d’autres non-mort sont présents sur le terrain et sont ses alliés : +6 dégâts et +1 Vitesse tant que la créature est en vie.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('gigantisme', 'Gigantisme', 'gigantisme', 'Cette créature peut utiliser l’arc de guerre géant avec les bras seulement.', 0, 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('gluant', 'Gluant', 'gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face aux dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1482');
