INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('golem', 'Golem', 'golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11358');
