INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('grand-bouclier', 'Grand bouclier', 'grand-bouclier', 'Tant qu’il porte un bouclier, réduit de moitié les dégâts infligés par des armes à distance ou de jet, ceux pour le porteur et les alliés adjacent à lui.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25832');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('grande-creature', 'Grande créature', 'grande-creature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 0, 'monstres', 'Bestiaire 2.0 › ligne 821');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('grande-reserve', 'Grande réserve', 'grande-reserve', 'La réserve de Nuage augmente à 40.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('grimpeur', 'Grimpeur', 'grimpeur', 'Cette créature possède un moyen de grimper les murs ou toutes surfaces en hauteur. Elle n’a pas besoin de jet pour les traverser et elle ne consomme pas son tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7792');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('grisatre', 'Grisâtre', 'grisatre', 'Cette créature peut annuler la météo (IC).', 0, 'monstres', 'Bestiaire 2.0 › ligne 14400');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('gros-projectile', 'Gros projectile', 'gros-projectile', 'L’arme de cette créature touche sur une zone de 2x2 au lieu d''une seule case.', 0, 'monstres', 'Bestiaire 2.0 › ligne 16649');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('haine-mutuelle', 'Haine mutuelle', 'haine-mutuelle', 'Cette créature inflige un bonus +10 dégâts contre la race dont elle est issue mais cette dernière a également le même bonus sur cette première.', 0, 'monstres', 'Décision R68 (réponse du chef, 2026-10-14)');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('humidification', 'Humidification', 'humidification', 'Dispose d''une protection qui va ignorer les 10 premiers dégâts qui vont lui être infligés lors d''un combat (se recharge tous les 3 tours).', 0, 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('hurlement', 'Hurlement', 'hurlement', 'Les alliés à 3 cases gagnent +4 à leur dégâts pendant 3 tours. Permet de donner des ordres précis à une créature canine alliée. (Action 1 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('hyper-pics', 'Hyper pics', 'hyper-pics', 'Les dégâts de pics évolutifs passent à 20.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('hyper-pics-plus', 'Hyper pics+', 'hyper-pics', 'Les dégâts de pics évolutifs passent à 25.', 0, 'monstres', 'Bestiaire 2.0 › ligne 27069');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('immateriel', 'Immatériel', 'immateriel', 'Cette créature est naturellement immunisée aux dégâts physiques (armes) , seules la magie, une arme spectrale ou une arme sous l’effet d’un sort “fer” peuvent la toucher.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11358');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('implosion', 'Implosion', 'implosion', 'Quand cette créature perd 25% de sa santé, elle explose et pose une zone de pression automatiquement sur une zone de 5x5 qui empêche les créature dans cette dernière de bouger pour leur prochain tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 13313');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('inalterable', 'Inaltérable', 'inalterable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11358');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('inarretable', 'Inarrêtable', 'inarretable', 'Cette créature ne peut être arrêtée dans son élan, seule une autre chose inarrêtable peut être utilisée pour l’arrêter.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('inerte', 'Inerte', 'inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 0, 'monstres', 'Bestiaire 2.0 › ligne 1482');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('initiative-extreme', 'Initiative extrême', 'initiative-extreme', 'Permet d''avoir un bonus de +10 au jet d''initiative.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10269');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('intervention', 'Intervention', 'intervention', 'Cette créature est capable de prendre un coup à la place d''un allié s''il est à côté de lui.', 0, 'monstres', 'Bestiaire 2.0 › ligne 27915');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('invisible', 'Invisible', 'invisible', 'Cette créature est invisible à l''œil nu, il faudra être inventif pour la repérer (météo, farine, terre, sable, etc …)', 0, 'monstres', 'Bestiaire 2.0 › ligne 13254');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('issue-de-leclair', 'Issue de l’éclair', 'issue-de-leclair', 'Immunisé à la paralysie.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('jet-de-sel', 'Jet de sel', 'jet-de-sel', 'Cette créature lance du sel et diminue de 2 cran la résistance à l’eau de la cible. (IC - 1 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 17526');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lame-canine', 'Lame canine', 'lame-canine', 'Les dégâts de taille ont un bonus de +8 aux dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lame-foudroyante', 'Lame foudroyante', 'lame-foudroyante', '(IC) En échange de 5 chakra, la prochaine attaque physique au contact libère une foudre qui inflige 1d8 dégâts qui va ignorer l’AM et l’AP de la cible.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10269');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lance-foudre', 'Lance foudre', 'lance-foudre', 'A son tour, cette créature envoie une lance faite entièrement de foudre dans le ciel en cloche et va atterrir sur un ennemi aléatoire qui pourra tenter un jet de défense. C’est un IC.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lanceur-de-poids', 'Lanceur de poids', 'lanceur-de-poids', 'Cette créature peut ajouter son score de Force à sa portée maximale de son arme à distance.', 0, 'monstres', 'Bestiaire 2.0 › ligne 16031');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lanceur-de-sorts', 'Lanceur de sorts', 'lanceur-de-sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrise maximum :', 1, 'monstres', 'Bestiaire 2.0 › ligne 957');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('larmes-du-paria', 'Larmes du paria', 'larmes-du-paria', 'Quand la créature tombe en dessous de 50% de santé = Pétrolier passe à 7 corruption, chaque attaque au contact subit force l''assaillant un jet de fermeté pour ne pas prendre "surcharge magique 1".', 0, 'monstres', 'Bestiaire 2.0 › ligne 821');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('laser-de-fer', 'Laser de fer', 'laser-de-fer', 'Tire tous les trois tours un laser qui passe à travers toutes les protections physiques, magiques, la barrière. Il est parable et esquivable. Ceci est un IC.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25413');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('laser-de-fer-plus', 'Laser de fer+', 'laser-de-fer', 'Tire tous les deux tours un laser qui passe à travers toutes les protections physiques, magiques, la barrière. Il est parable et esquivable. Ceci est un IC.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25470');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('laser-de-fer-plus-plus', 'Laser de fer++', 'laser-de-fer', 'Tire tous les tours un laser qui passe à travers toutes les protections physiques, magiques, la barrière. Il est parable et esquivable. Ceci est un IC.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25527');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lenteur', 'Lenteur', 'lenteur', 'Cette créature à un malus de 5 à l’initiative.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26022');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('liane-ralentisseur', 'Liane ralentisseur', 'liane-ralentisseur', 'Les sorts ou armes en lien avec les plantes qui touchent une cible lui retirent également 1 de vitesse pour son prochain tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lien-forestier', 'Lien forestier', 'lien-forestier', 'Tant qu’il est dans la forêt, il bénéficie d’une bonus à la réussite de 5% et d’un bonus aux dégâts de 2. Sortir de la forêt fait qu’il peut en mourir.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10707');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lumiere-de-force', 'Lumière de force', 'lumiere-de-force', 'Chaque début de tour, cette créature bénéficie d’un champ de force qui encaisse 5 dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 15426');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('lumiere-de-super-force', 'Lumière de super force', 'lumiere-de-super-force', 'Annule 5 dégâts d’une attaque encaissé, cette réduction se recharge après chaque attaque et elle n’est pas affectée par les attaques qui ignorent les défenses.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25701');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('magicien', 'Magicien', 'magicien', 'Les dégâts de Glace, Ombre et de Foudre augmentent de +10.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('magie-aleatoire', 'Magie aléatoire', 'magie-aleatoire', 'Cette créature commence avec une magie aléatoire, le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('magie-et-acier', 'Magie et Acier', 'magie-et-acier', '+3 aux dégâts des armes et des sorts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('maitre-des-cieux', 'Maître des cieux', 'maitre-des-cieux', 'Cette créature est totalement immunisée à la magie du Vent et de la Foudre.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18820');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('maitre-du-silence', 'Maître du silence', 'maitre-du-silence', 'Cette créature ne peut pas subir les sorts ou effets qui empêche d’utiliser la magie.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20822');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('maladie-de-la-pierre', 'Maladie de la Pierre', 'maladie-de-la-pierre', 'Quand cette créature fait un coup critique à l’attaque, il oblige un jet de vigueur à la cible, si cette dernière rate, elle prend “pétrification 1”. Si la victime fait un échec critique à son jet, elle contracte la Maladie de la Pierre.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26077');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mantelet-des-tenebres', 'Mantelet des ténèbres', 'mantelet-des-tenebres', 'Impose un malus de 10% aux jets de parade/esquive aux ennemis à 3 cases ou moins.', 0, 'monstres', 'Bestiaire 2.0 › ligne 15744');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('matiere-seche', 'Matière sèche', 'matiere-seche', 'La peau de cette créature réagit à certaines météo :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mes-precieux', 'Mes précieux !', 'mes-precieux', 'Cette créature a la possibilité de voler une arme à une main, un accessoire, un objet à la ceinture ou de l’or dans la bourse d’une cible qui possède moins de 20% de sa santé max. La victime peut tenter un jet de Stabilité ou Réflexe, si elle rate : L’objet est perdu et la créature va la poser plus loin pour revenir au combat, dès qu’il a volé 3 objets, il fuit le combat.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7190');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('meteo-favorable', 'Météo favorable', 'meteo-favorable', 'Tant que cette créature est dans une météo qui avantage sa magie, il gagne 10 aux dégâts qu’il inflige.', 0, 'monstres', 'Bestiaire 2.0 › ligne 13536');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('meteo-invisible', 'Météo invisible', 'meteo-invisible', 'Tant que cette créature est dans une météo qui avantage sa magie, il est capable en échange de ses 3IC de se rendre invisible pendant 2 tours. 2 fois/combat.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5591');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('meteo-sournoise', 'Météo sournoise', 'meteo-sournoise', 'Tant que cette créature est dans une météo qui avantage sa magie, il est capable de faire des dégâts sournois à hauteur de 2d4.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('meteore', 'Météore', 'meteore', 'Permet de sauter sur une case et infliger -1d dégâts sur une zone de 3x3. (Portée = Vitesse)', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mimetisme', 'Mimétisme', 'mimetisme', 'Capable de copier un don d’une classe d’un adversaire si il a été enclenché.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mimique', 'Mimique', 'mimique', 'Imite le jet de l''agresseur lors d''un combat. Si c''est une réussite critique, un jet de chance est nécessaire. (2 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('minus', 'Minus', 'minus', 'Cette créature est petite, elle impose un malus de {10}% aux jets des adversaires qui tentent de la toucher.', 0, 'monstres', 'Bestiaire 2.0 › ligne 10877');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('miroir-partiel', 'Miroir partiel', 'miroir-partiel', 'Renvoi à hauteur de 25% des effets du sort de l’adversaire (l’agresseur peut se défendre contre cette contre attaque si c’est possible)', 0, 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mon-precieux', 'Mon précieux !', 'mon-precieux', 'Une fois par combat, cette créature a la possibilité de voler un accessoire, un objet à la ceinture ou de l’or dans la bourse d’une cible qui possède moins de 20% de sa santé max. La victime peut tenter un jet de Stabilité ou Réflexe, si elle rate : L’objet est perdu et la créature s''enfuit.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7073');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('morsure-aspirante-bleue', 'Morsure aspirante bleue', 'morsure-aspirante-bleue', 'La morsure de cette créature est capable d’aspirer le chakra de sa victime à hauteur de {25}% par rapport aux dégâts infligés avec l’attaque.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7521');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mortier', 'Mortier', 'mortier', 'Cette créature possède une arme qui peut tirer des projectiles et est considérée comme une arbalète dans la stats qu’il faut utiliser. Les projectiles tirés par cette arme ignore 3AP mais sont détruits après utilisation.', 0, 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('moteur-a-vapeur', 'Moteur à vapeur', 'moteur-a-vapeur', 'Quand il prend une attaque de l’élément Eau ou Vent, sa vitesse augmente de +2 pendant 2 tours. Si la météo est positive pour le Vent ou l’Eau, sa vitesse de base monte à 4 et il a +3 à l’initiative.', 0, 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('moteur-thermique', 'Moteur thermique', 'moteur-thermique', 'Cette créature absorbe les dégâts de l’élément feu, si un dégâts de feu est tenté sur lui, ses dégâts augmente de 5 et sa vitesse de 1 pendant 2 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 13858');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('mourir-peut-attendre', 'Mourir peut attendre', 'mourir-peut-attendre', 'Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5793');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('multi-fer', 'Multi-fer', 'multi-fer', 'Cette créature est capable d’activer en IC n’importe quel sort de type “fer” mais sans avoir le bonus de dégâts. Dure 3 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25413');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('multi-fer-plus', 'Multi-fer+', 'multi-fer', 'Cette créature est capable d’activer en IC n’importe quel sort de type “fer” et avoir un bonus de +3 aux dégâts. Dure 3 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25470');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('multi-fer-plus-plus', 'Multi-fer++', 'multi-fer', 'Cette créature est capable d’activer en IC n’importe quel sort de type “fer” et d’avoir un bonus de +6 aux dégâts. Dure 3 tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25527');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('multi-racines', 'Multi-racines', 'multi-racines', 'Cette créature est capable avec l’une de ses *armes de frapper l’intégralité des ennemis sur le terrain et sans limite de portée.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('necrophage', 'Nécrophage', 'necrophage', 'Manger de la viande de cadavre redonne 3d8 barrière.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('neige-permanente', 'Neige permanente', 'neige-permanente', 'Invoque la météo “neige” en entrant sur le terrain et fait perdurer tant que personne ne la change.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('nerveux', 'Nerveux', 'nerveux', 'Cette créature à +4 à l’initiative.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('non-mort', 'Non-Mort', 'non-mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('nuage-colerique', 'Nuage colérique', 'nuage-colerique', 'Si 30 compteurs de Nuage = Peut sacrifié 3IC pour une attaque supplémentaire (1 fois/combat)', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('nuage-determinant', 'Nuage déterminant', 'nuage-determinant', 'Si 10 compteurs de Nuage = +5% à tous les jets de dés.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('nuage-maudit', 'Nuage maudit', 'nuage-maudit', 'Si 20 compteurs de Nuage = Les attaques de la créature impose l’effet du sort d’ombre “malédiction” pendant 1 tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('nuage-rapide', 'Nuage rapide', 'nuage-rapide', 'Si 15 compteurs de Nuage = +1 Vitesse', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
