INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('obscurite-avantageuse', 'Obscurité avantageuse', 'obscurite-avantageuse', 'Cette créature est avantagée dans le noir, il impose un malus de 5% à tout les jets hostiles envers lui et toutes ses attaques font 1d de dégâts supplémantaire.', 0, 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('optimisation', 'Optimisation', 'optimisation', 'Obtient 3 compteurs au lieu de 2 pour le don “Produit du nuage”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 1302');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('ottar', 'Ottar', 'ottar', 'Cette créature est un Ottar et est donc totalement invulnérable au contrôle mental, à la peur et à la couardise.', 0, 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('pandemie', 'Pandémie', 'pandemie', 'Quand un ennemi passe à côté de ses alliés alors qu’il souffre d’un poison, son allié est forcé de faire un jet de vigueur pour ne pas prendre le poison.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26713');
