INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('perce-am', 'Perce-AM', 'perce-am', 'Les sorts de cette créature ignorent 4AM.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8185');
