INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('perce-muraille', 'Perce muraille', 'perce-muraille', 'L’attaque de cette créature perce 6 AP.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20564');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('petit-et-rapide', 'Petit et rapide', 'petit-et-rapide', 'La division 2 et 3 ont un bonus de +4 à l’initiative et +1 à la vitesse.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('petit-sournois', 'Petit sournois', 'petit-sournois', 'Quand l’adversaire n’est pas attentif à l’attaquant, permet d’infliger un bonus de 1d4 dégâts en plus des dégâts de l’arme.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24793');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('petite-regeneration', 'Petite régénération', 'petite-regeneration', 'Cette créature récupère 5 santé au début de chacun de ses tours.', 0, 'monstres', 'Bestiaire 2.0 › ligne 2335');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('petrolier', 'Pétrolier', 'petrolier', 'Chaque attaque qui touche inflige 5 corruption.', 0, 'monstres', 'Bestiaire 2.0 › ligne 705');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('petronage', 'Pétronage', 'petronage', 'La vitesse de nage dans le pétrole ou les marais est doublée, la vitesse augmente de +2 sous la météo “Pluie pétrole”. Peut nager dans de l’eau non magique.', 0, 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('phalange', 'Phalange', 'phalange', 'L’arme de cette créature ignore l’effet des boucliers.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('phare', 'Phare', 'phare', 'Tous les 3 tours, la créature fait exploser une lumière qui inflige 10 dégâts fixes qui perce AP/AM et forcera le jet de vigueur aux ennemis sur le terrain pour ne pas qu’ils prennent “aveuglement 1”', 0, 'monstres', 'Bestiaire 2.0 › ligne 15481');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('photophile', 'Photophile', 'photophile', 'Cette créature attire les sorts d''attaques de lumière vers lui et ne prend pas de dégâts des sorts de soin de la lumière.', 0, 'monstres', 'Bestiaire 2.0 › ligne 25588');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('pics-elementaires', 'Pics élémentaires', 'pics-elementaires', 'Les pics peuvent infliger des dégâts élémentaires liés à la magie de la créature.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26831');
