INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('produit-du-nuage', 'Produit du Nuage', 'produit-du-nuage', 'Cette créature produit une sorte de nuage de kcirevam en permanence quand il est en stress. Chaque attaque qu’il prend et chaque tour de jeu terminée, il obtient 2 compteurs de Nuage. Il gagne +4 aux dégâts tous les 10 compteurs (pour un maximum de 30).', 0, 'monstres', 'Bestiaire 2.0 › ligne 1062');
