INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('science-du-critique-plus-plus', 'Science du critique++', 'science-du-critique', 'Cette créature a +5 à la réussite critique et à l’échec critique.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6002');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('serviteur-toxique', 'Serviteur toxique', 'serviteur-toxique', 'Cette créature n’attaque pas directement, elle se cache derrière une cage d’os indestructible et lance ses invocations contre ses ennemis, elle peut en invoquer 4 à la fois, sans jet, a accès à toutes les invocations de la nécromancie et les remplace le tour après leur mort. Une fois qu’une invocation est tuée, la santé qu’elle possédait sera infligée contre la santé du boss (pas sa barrière). Il peut lancer les invocations selon son niveau de puissance magique.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('soif-de-combat', 'Soif de combat', 'soif-de-combat', 'Quand cette créature tombe en dessous de 75% de santé, +3 aux dégâts. En dessous de 50%, +5 aux dégâts. En dessous de 25%, +7 aux dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19500');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('soin-non-mort', 'Soin non-mort', 'soin-non-mort', 'Cette créature est capable de soigner ses alliés non-morts avec la magie de la lumière.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20080');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('son-strident', 'Son strident', 'son-strident', 'Cette créature est capable de faire résonner un son strident sur tout le terrain qui va empêcher l’utilisation de la magie pendant 2 tours complets. (4 tours de recharge)', 0, 'monstres', 'Bestiaire 2.0 › ligne 24536');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('souffle-elementaire', 'Souffle élémentaire', 'souffle-elementaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquence pour ne pas prendre l''altération d''état).', 0, 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('sournois', 'Sournois', 'sournois', 'Quand l’adversaire n’est pas attentif à l’attaquant, permet d’infliger un bonus de 2d4 dégâts en plus des dégâts de l’arme.', 0, 'monstres', 'Bestiaire 2.0 › ligne 3317');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('squelettique', 'Squelettique', 'squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('statue', 'Statue', 'statue', 'Si la créature n’a pas bougé durant ce tour, elle gagne +5AP mais perd 6 INI, et ceux jusqu''au début de son prochain tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('sucon', 'Suçon', 'sucon', 'Chaque attaque redonne de la santé ou de la barrière (selon ce qui est touché) à hauteur de 50% des dégâts infligés.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21295');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('sujet-epineux', 'Sujet épineux', 'sujet-epineux', 'En posture de défense, cette créature inflige 8 dégâts lors d’une parade parfaite.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5856');
