INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('sulfateuse', 'Sulfateuse', 'sulfateuse', 'Les arbalètes n’ont plus de recharge longue.', 0, 'monstres', 'Bestiaire 2.0 › ligne 16901');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('super-12', 'Super 12', 'super-12', 'Si cette créature fait un 12, c’est une réussite critique.', 0, 'monstres', 'Bestiaire 2.0 › ligne 16962');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('super-armure', 'Super armure', 'super-armure', 'Cette créature possède une protection qui va demander un certain nombre de dégâts pour être détruite (25 dégâts), elle doit être détruite en un seul coup sinon elle se reconstruit immédiatement. Si jamais elle est détruite, elle revient au bout de 2 tours. Cette armure empêche tout dégâts à la santé de la créature, peu importe les moyens utilisés.', 0, 'monstres', 'Bestiaire 2.0 › ligne 28385');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('super-aura', 'Super aura', 'super-aura', 'Les passifs en zone ont une portée augmentée de 2.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18526');
