INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('super-explosion', 'Super explosion', 'super-explosion', 'Les projectiles de cette créature touchent une zone de 3x3 au lieu de 2x2.', 0, 'monstres', 'Bestiaire 2.0 › ligne 14690');
