INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('super-odorat', 'Super Odorat', 'super-odorat', 'Cette créature ne peut pas avoir de croix à la Perception.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
