INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('surchauffe', 'Surchauffe', 'surchauffe', 'Permet de consommer le triple du coût du sort pour augmenter ses dégâts de 2d.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6140');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('surpuissance', 'Surpuissance', 'surpuissance', 'Pendant le “Face et Face”, la créature obtient un bonus de +7 à tous les dégâts.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21897');
