INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('symbiose-eau', 'Symbiose eau', 'symbiose-eau', 'Tant qu’elle est dans l’eau, cette créature inflige +3 à tous ses dégâts et récupère 2 santé à chaque début de tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 957');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('tambour', 'Tambour', 'tambour', 'Peut frapper le sol pour créer une secousse (cercle de 7). Jet de stabilité/réflexe pour les cibles dans la zone, si le jet est raté, incapacité de se déplacer et malus de 10% sur tous les jets pour le prochain tour.', 0, 'monstres', 'Bestiaire 2.0 › ligne 14465');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('temeraire', 'Téméraire', 'temeraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5856');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('temeraire-raisonne', 'Téméraire raisonné', 'temeraire-raisonne', 'Cette créature n’a pas le malus pour toucher quand elle est en offensif', 0, 'monstres', 'Bestiaire 2.0 › ligne 28033');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('terraformation', 'Terraformation', 'terraformation', 'A chaque fois que la créature perd 30% de sa santé max, il se déplace gratuitement sur le terrain et ce dernier est totalement changé avec des murs et des obstacles nouveaux.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('terrain-avantageux', 'Terrain avantageux', 'terrain-avantageux', 'Si cette créature est dans un terrain qui lui est favorable = +2 à la réussite critique et +3 aux dégâts. (Terrain favorable = Forêt, Plateau, Montagne)', 0, 'monstres', 'Bestiaire 2.0 › ligne 20274');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('terrain-favorable', 'Terrain favorable', 'terrain-favorable', 'Si jamais la météo est "Vent violent" ou "Tempête de sable", ses dégâts augmentent de +8 et son arme a le double de sa portée.', 0, 'monstres', 'Bestiaire 2.0 › ligne 7256');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('tete-fongique', 'Tête fongique', 'tete-fongique', 'La tête est protégée et n’est plus considérée comme un point faible.', 0, 'monstres', 'Bestiaire 2.0 › ligne 28322');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('tome-2-fois-2-couleurs', 'Tome 2 fois 2 couleurs', 'tome-2-fois-2-couleurs', 'Cette créature dispose de 2 paires de magies qui utilise d’une façon qui lui est propre (voir Pile ou Face). Il utilisera les sorts qui correspondent à son niveau de puissance, il ne peut pas atteindre les sorts niveau 5 de puissance magique.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21759');
