INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('totem-du-neant', 'Totem du néant', 'totem-du-neant', 'Les ennemis à 3 cases autour de la créature ont un malus de 10% à tous les jets qui implique la volonté.', 0, 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('tourner-pour-gagner', 'Tourner pour gagner', 'tourner-pour-gagner', 'Quand cette créature fait une attaque cyclone, il n’a pas de malus.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19930');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('transition-chaotique', 'Transition chaotique', 'transition-chaotique', 'Quand la créature change d’état, un effet est provoqué :
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('tremblement', 'Tremblement', 'tremblement', 'Dans le sol, cette créature fait remuer le sol si fort qu’elle force un jet de stabilité à sa cible pour ne pas qu’elle tombe par terre.', 0, 'monstres', 'Bestiaire 2.0 › ligne 20622');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('triumvirat-instable-fenrir', 'Triumvirat instable fenrir', 'triumvirat-instable-fenrir', 'Cette créature est liée aux magies de la Foudre, Glace et Ombre et est capable d’utiliser ces magies selon son niveau. Mais les faiblesses aux altérations d’états s’en trouvent amplifiées.', 0, 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('tu-ne-passes-pas', 'Tu ne passes pas', 'tu-ne-passes-pas', 'Permet de bloquer les adversaires dans sa zone d’influence complète. Permet également d’intercepter les attaques avec un jet de défense réussi.', 0, 'monstres', 'Bestiaire 2.0 › ligne 28141');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('uni-dans-la-mort', 'Uni dans la mort', 'uni-dans-la-mort', 'Cette créature est en symbiose complète avec une autre, mettre hors de combat l’une d’entre n’est pas suffisant, il est nécessaire que les deux créatures meurent quasiment au même moment. Si l’une d’entre elle tombe au combat, elle se relèvera après un tour avec 10% de sa santé.', 0, 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('verre-pile', 'Verre pilé', 'verre-pile', 'À chaque coup physique encaissé, des éclats de verre sont envoyés à l’attaquant, infligeant 3d{6} dégâts neutres.', 0, 'monstres', 'Bestiaire 2.0 › ligne 6204');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vise-le-tresor', 'Vise le trésor', 'vise-le-tresor', 'Cette créature va se concentrer sur les adversaires les plus “riches”.', 0, 'monstres', 'Bestiaire 2.0 › ligne 21100');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('visualisation', 'Visualisation', 'visualisation', 'Le malus pour viser une partie du corps diminue de 5%.', 0, 'monstres', 'Bestiaire 2.0 › ligne 26259');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vol', 'Vol', 'vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 0, 'monstres', 'Bestiaire 2.0 › ligne 5793');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vomi', 'Vomi', 'vomi', 'La créature vomit une espèce d’acide qui va s’infiltrer dans les armures ou vêtements et brûler la peau. Inflige pendant 2 tours 2d6 dégâts perce armure et va retirer un cran de solidité au morceau d’armure touché (une seule fois).', 0, 'monstres', 'Bestiaire 2.0 › ligne 21530');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vomi-plus', 'Vomi+', 'vomi', 'La créature vomi une espèce d’acide qui va s’infiltrer dans les armures ou vêtements et brûler la peau. Inflige pendant 2 tours 3d6 dégâts perce armure et va retirer un cran de solidité au morceau d’armure touché (une seule fois).', 0, 'monstres', 'Bestiaire 2.0 › ligne 21584');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vraiment-sournois', 'Vraiment sournois', 'vraiment-sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 4d4 dégâts en plus des dégâts de l''arme.', 0, 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vue-ouie-claire', 'Vue/Ouïe claire', 'vue-ouie-claire', 'Cette créature ne peut être rendue aveugle ou sourde.', 0, 'monstres', 'Bestiaire 2.0 › ligne 18702');
INSERT INTO monstre_capacite_commune (id, nom, nom_cle, description, liste_de_sorts, origine, source_ref) VALUES ('vulnerabilite-acide', 'Vulnérabilité acide', 'vulnerabilite-acide', 'Cette créature possède une vulnérabilité contre les dégâts d’acide, les sorts affligeants des dégâts d’acide ne sont pas annulés mais leur effets secondaires oui.', 0, 'monstres', 'Bestiaire 2.0 › ligne 24536');
